-- public.barrel_for(p_world uuid, p_uid uuid, p_kind text)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.barrel_for(p_world uuid, p_uid uuid, p_kind text)
 RETURNS placed
 LANGUAGE sql
 STABLE
AS $function$
  select p.* from placed p
  where p.world_id = p_world and p.kind = 'furniture'
    and holds_liquid(p) and not is_well(p)
    and (placed_litres(p) <= 0 or placed_liquid(p) = p_kind)
    and placed_litres(p) < liquid_capacity(p)
    and near_piece(p_world, p_uid, p, 2.6)
  order by placed_litres(p), p.id
  limit 1
$function$
